describe('Video Player Responsive Resize on Tablet Viewports', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('ipad-2');
  });

  it('should resize video player proportionally on tablet viewport', () => {
    cy.get('[data-testid="video-player"]').should('be.visible');

    cy.get('[data-testid="video-player"]').then(($player) => {
      const playerWidth = $player.width();
      const playerHeight = $player.height();
      const aspectRatio = playerWidth / playerHeight;

      expect(aspectRatio).to.be.closeTo(16 / 9, 0.1);
    });

    cy.get('[data-testid="video-player"] video').should('have.css', 'width', '100%');
    cy.get('[data-testid="video-player"] video').should('have.css', 'height', 'auto');
  });

  it('should maintain aspect ratio when resizing between tablet orientations', () => {
    cy.get('[data-testid="video-player"]').then(($player) => {
      const initialWidth = $player.width();
      const initialHeight = $player.height();
      const initialRatio = initialWidth / initialHeight;

      cy.viewport('ipad-2', 'landscape');

      cy.get('[data-testid="video-player"]').then(($resizedPlayer) => {
        const resizedWidth = $resizedPlayer.width();
        const resizedHeight = $resizedPlayer.height();
        const resizedRatio = resizedWidth / resizedHeight;

        expect(resizedRatio).to.be.closeTo(initialRatio, 0.1);
        expect(resizedWidth).to.be.greaterThan(initialWidth);
        expect(resizedHeight).to.be.greaterThan(initialHeight);
      });
    });
  });

  it('should handle edge case of very small tablet viewport', () => {
    cy.viewport(480, 600);

    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').should('have.css', 'max-width', '100%');

    cy.get('[data-testid="video-player"]').then(($player) => {
      const playerWidth = $player.width();
      expect(playerWidth).to.be.lessThanOrEqual(480);
    });
  });

  it('should display video controls properly on tablet viewport', () => {
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"] [data-testid="play-button"]').should('be.visible');
    cy.get('[data-testid="video-player"] [data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="video-player"] [data-testid="volume-control"]').should('be.visible');
    cy.get('[data-testid="video-player"] [data-testid="fullscreen-button"]').should('be.visible');
  });

  it('should handle fullscreen mode on tablet without breaking aspect ratio', () => {
    cy.get('[data-testid="video-player"]').then(($player) => {
      const playerWidth = $player.width();
      const playerHeight = $player.height();
      const aspectRatio = playerWidth / playerHeight;

      cy.get('[data-testid="video-player"] [data-testid="fullscreen-button"]').click();

      cy.get('[data-testid="video-player"]').should('have.class', 'fullscreen');

      cy.get('[data-testid="video-player"]').then(($fullscreenPlayer) => {
        const fullscreenWidth = $fullscreenPlayer.width();
        const fullscreenHeight = $fullscreenPlayer.height();
        const fullscreenRatio = fullscreenWidth / fullscreenHeight;

        expect(fullscreenRatio).to.be.closeTo(aspectRatio, 0.1);
      });
    });
  });
});
